/*!
 * Crafted with ❤ by Salla
 */
/**
 * Order-options gate for the fast-checkout widget — keeps <salla-add-product-button> thin.
 * Intercepts the widget click → runs the order-options modal → injects the result → re-fires the click.
 */
const PRODUCT_FORM_SELECTOR = 'form.product-form';
export class OrderOptionsGate {
    constructor(host, productId) {
        this.host = host;
        this.productId = productId;
        /** True on the re-fired click so it passes through instead of re-gating. */
        this.collected = false;
        /** Live PDP price (one onPriceUpdated subscription per widget). */
        this.livePrice = 0;
    }
    /** Attach once to the widget. Returns false when there's no widget (e.g. product cards) so the caller retries. */
    static attach(host, productId) {
        const widget = host.querySelector('salla-mini-checkout-widget');
        if (!widget)
            return false;
        const gate = new OrderOptionsGate(host, String(productId));
        // One subscription per widget (PDP only) — no per-card leak.
        salla.product?.event?.onPriceUpdated?.((response) => {
            gate.livePrice = Number(response?.data?.price) || gate.livePrice;
        });
        widget.addEventListener('click', (event) => gate.handleWidgetClick(event, widget), true);
        return true;
    }
    /** Quantity from the same form the widget submits (PRODUCT_FORM_SELECTOR), not the button's nearest form. */
    getSelectedQuantity() {
        try {
            const form = document.querySelector(PRODUCT_FORM_SELECTOR);
            const data = form?.getElementSallaData?.();
            const qty = Number(data instanceof FormData ? data.get('quantity') : data?.quantity);
            if (Number.isFinite(qty) && qty > 0)
                return qty;
        }
        catch {
            // fall through to the attribute
        }
        return Number(this.host.getAttribute('quantity')) || 1;
    }
    async handleWidgetClick(event, widget) {
        if (this.collected) {
            this.collected = false;
            return;
        }
        event.preventDefault();
        event.stopImmediatePropagation();
        if (!await this.validatePdpOptions())
            return;
        if (salla.config.isGuest()) {
            salla.api.auth.requireLoginThen('salla-add-product-button::oo.after-login', () => this.handleWidgetClick(event, widget));
            return;
        }
        widget.classList.add('s-add-product-button-busy');
        let resp;
        try {
            resp = await salla.api.withoutNotifier(() => salla.product.api.getOrderOptions([{ id: this.productId, quantity: this.getSelectedQuantity() }]));
        }
        catch (error) {
            salla?.logger?.warn?.('order-options: fetch failed', error);
            widget.classList.remove('s-add-product-button-busy');
            this.resumeWidget(widget);
            return;
        }
        widget.classList.remove('s-add-product-button-busy');
        const items = resp?.data?.order_options || [];
        if (!items.length) {
            this.resumeWidget(widget);
            return;
        }
        const basePrice = this.livePrice > 0
            ? this.livePrice
            : Number(resp?.data?.products?.[0]?.price?.amount) || 0;
        const modal = this.ensureModal();
        try {
            const result = await modal.open({ orderOptions: items, basePrice });
            this.injectIntoMini(result?.orderOptions || []);
            this.resumeWidget(widget);
        }
        catch {
            // user dismissed — widget stays blocked, they re-click to retry.
        }
    }
    async validatePdpOptions() {
        const optionsEl = document.querySelector(`salla-product-options[product-id="${this.productId}"]`);
        if (!optionsEl)
            return true;
        if (typeof optionsEl.validateAndScroll === 'function') {
            return await optionsEl.validateAndScroll();
        }
        if (typeof optionsEl.reportValidity === 'function') {
            return await optionsEl.reportValidity();
        }
        return true;
    }
    /** Inject order_options into the next cart-add payload via `cart::before.add.item` (one-shot, scoped to productId). */
    injectIntoMini(orderOptions) {
        if (!orderOptions.length)
            return;
        const productId = this.productId;
        const onceHandler = (eventData) => {
            if (String(eventData?.id) !== String(productId))
                return;
            try {
                eventData?.payload?.set?.('order_options', orderOptions);
            }
            finally {
                salla.event.off('cart::before.add.item', onceHandler);
            }
        };
        salla.event.on('cart::before.add.item', onceHandler);
    }
    ensureModal() {
        let modal = document.querySelector('salla-order-options-modal');
        if (!modal) {
            modal = document.createElement('salla-order-options-modal');
            document.body.appendChild(modal);
        }
        return modal;
    }
    resumeWidget(widget) {
        this.collected = true;
        // Real click target lives in the widget's shadow DOM.
        const innerBtn = widget.shadowRoot?.querySelector?.('.s-fast-checkout-button');
        if (innerBtn) {
            innerBtn.click();
        }
        else if (typeof widget.click === 'function') {
            widget.click();
        }
    }
}
